using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace AkilliKisayol {
 public static class CustomThemeTests {
  public static void Unit(Action<bool,string> check){
   var basis=ThemeCatalog.Resolve("graphite",true);var custom=ThemeFiles.Create(basis);custom.Name="Ocean";custom.Background="#101A2B";custom.AccentColor="#FF9988";custom.PeachColor="#DDBB99";check(ThemeFiles.Validate(custom)==null&&custom.Id!=basis.Id&&basis.Background!="#101A2B","Custom themes are editable copies with their own identities; presets stay unchanged");var invalid=custom.Copy();invalid.Background="red";check(ThemeFiles.Validate(invalid)!=null,"Theme files accept explicit opaque hex colors instead of arbitrary markup or color expressions");invalid=custom.Copy();invalid.Name=" ";check(ThemeFiles.Validate(invalid)!=null,"Custom themes require a usable name");
   string folder=Path.Combine(Path.GetTempPath(),"MakroPlus-custom-theme-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{string file=Path.Combine(folder,"theme.makrotheme.json");ThemeFiles.Write(custom,file);var imported=ThemeFiles.Read(file);check(imported.Name==custom.Name&&imported.Background==custom.Background&&imported.Accent==custom.Accent&&imported.Peach==custom.Peach&&imported.Id!=custom.Id,"Theme-only export/import preserves custom colors and creates an independent imported identity");check(!File.ReadAllText(file).Contains("Bindings")&&!File.ReadAllText(file).Contains("ModelPath"),"Shared theme files contain palette data rather than shortcuts or model settings");var state=new State{ThemeId=custom.Id,CustomThemes=new List<ThemePalette>{custom}};string settings=Path.Combine(folder,"settings.json");Storage.Write(state,settings);var loaded=Storage.Read(settings);check(loaded.ThemeId==custom.Id&&ThemeCatalog.Resolve(loaded).Background==custom.Background,"A custom theme remains selected after restarting from saved settings");Transfer.Export(state,settings);var transferred=Transfer.Import(new State(),Storage.Read(settings),new Dictionary<string,string>(),false);check(transferred.State.CustomThemes.Count==1&&ThemeCatalog.Resolve(transferred.State).Background==custom.Background,"Full settings transfers include custom themes and their selected preference");var conflict=custom.Copy();conflict.Background="#203040";var existing=new State{ThemeId=custom.Id,CustomThemes=new List<ThemePalette>{conflict}};var collision=Transfer.Import(existing,state,new Dictionary<string,string>(),false);check(collision.State.CustomThemes.Count==2&&collision.State.ThemeId!=custom.Id&&ThemeCatalog.Resolve(collision.State).Background==custom.Background&&existing.CustomThemes.Count==1,"Importing a different palette with an existing identity preserves both themes and selects the incoming copy on a fresh workspace");
    var renamed=custom.Copy();renamed.Name="Renamed Ocean";var metadata=Transfer.Import(new State{CustomThemes=new List<ThemePalette>{renamed}},state,new Dictionary<string,string>(),false);check(metadata.State.CustomThemes.Count==2&&ThemeCatalog.Resolve(metadata.State).Name==custom.Name,"Theme imports preserve both names when an identity is reused with different metadata");existing.Bindings.Add(new Binding{Key=119});collision=Transfer.Import(existing,state,new Dictionary<string,string>(),false);check(collision.State.ThemeId==existing.ThemeId&&ThemeCatalog.Resolve(collision.State).Background==conflict.Background,"Imports preserve the active custom theme of an existing workspace");
    File.WriteAllText(file,"{\"Format\":\"Unknown\",\"Version\":1}");bool rejected=false;try{ThemeFiles.Read(file);}catch(InvalidDataException){rejected=true;}check(rejected,"Unsupported shared-theme formats are rejected without changing preferences");File.WriteAllText(file,"not JSON");rejected=false;try{ThemeFiles.Read(file);}catch(InvalidDataException){rejected=true;}check(rejected,"Malformed shared-theme JSON is handled as an import error");
    invalid=custom.Copy();invalid.Background="invalid";state.CustomThemes=new List<ThemePalette>{invalid};ThemeCatalog.Normalize(state);check(state.CustomThemes.Count==0&&state.ThemeId=="graphite","An invalid stored palette falls back to a readable preset without preventing startup");
   }finally{foreach(string file in Directory.GetFiles(folder))File.Delete(file);Directory.Delete(folder);}
  }
  static IEnumerable<Button> Buttons(DependencyObject parent){for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);if(child is Button)yield return (Button)child;foreach(var nested in Buttons(child))yield return nested;}}
  public static void Ui(MainWindow window,Action<bool,string> check,Action<Window,string> screenshot){
   int attempts=0;var retry=new ThemeEditorWindow(ThemeFiles.Create(ThemeCatalog.Resolve("graphite",true)),p=>++attempts>1){Owner=window};Exception retryFailure=null;Application.Current.Dispatcher.BeginInvoke(new Action(()=>{try{retry.FieldForTest("Name","Retry fixture");var button=Buttons(retry).Single(b=>Convert.ToString(b.Content)=="Save and apply");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(retry.IsVisible&&retry.Result==null&&retry.DraftForTest().Name=="Retry fixture","A failed persistence callback keeps the designer and edited draft available for retry");button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception error){retryFailure=error;retry.Close();}}));bool? retried=retry.ShowDialog();if(retryFailure!=null)throw retryFailure;check(retried==true&&attempts==2,"Saving can succeed on retry without re-entering theme edits");
   var draft=ThemeFiles.Create(ThemeCatalog.Resolve("graphite",true));var editor=new ThemeEditorWindow(draft){Owner=window};Exception failure=null;Application.Current.Dispatcher.BeginInvoke(new Action(()=>{try{editor.FieldForTest("Name","Ocean custom");editor.FieldForTest("Background","#182638");editor.FieldForTest("AccentColor","oops");check(!editor.CanSaveForTest,"Designer disables saving an incomplete or invalid hex color");editor.FieldForTest("AccentColor","#F38983");editor.FieldForTest("PeachColor","#F1C696");check(editor.CanSaveForTest&&draft.Background!="#182638","Live preview edits a draft without changing the source theme");screenshot(editor,"custom-theme-designer-preview.png");Buttons(editor).Single(b=>Convert.ToString(b.Content)=="Save and apply").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception error){failure=error;editor.Close();}}));bool? result=editor.ShowDialog();if(failure!=null)throw failure;check(result==true&&editor.Result.Background=="#182638"&&editor.Result.Accent=="#F38983","The designer's real save action returns the edited palette");check(window.SaveThemeForTest(editor.Result)&&((SolidColorBrush)Application.Current.Resources["Bg"]).Color==editor.Result.Brush("#182638").Color,"Saving a custom theme applies it to the real application window");var revision=editor.Result.Copy();revision.Name="Ocean revised";revision.Background="#152435";check(window.SaveThemeForTest(revision),"An existing custom theme can be edited and saved under the same identity");window.ProductViewForTest("Appearance");check(Buttons(window).Count(b=>System.Windows.Automation.AutomationProperties.GetName(b).StartsWith("Ocean revised theme"))==1&&!Buttons(window).Any(b=>System.Windows.Automation.AutomationProperties.GetName(b).StartsWith("Ocean custom theme")),"Editing updates one gallery entry instead of duplicating it");check(Buttons(window).Any(b=>Convert.ToString(b.Content)=="Edit selected")&&Buttons(window).Any(b=>Convert.ToString(b.Content)=="Delete selected"),"User-created themes expose edit and delete controls");screenshot(window,"custom-theme-gallery-preview.png");
  }
 }
}
